<template>

    <div class="container">

        <h1>Tabla Inventario</h1>

        <table border="1">

    <thead>

        <tr>
            <th>ID</th>
            <th>Nombre Producto</th>
            <th>Cantidad</th>
            <th>Precio</th>
        </tr>

    </thead>

    <tbody>

        |<tr v-for="producto in productos" :key="producto.id">

            <td>{{ producto.id }}</td>
            <td>{{ producto.nombreProducto }}</td>
            <td>{{ producto.cantidad }}</td>
            <td>{{ producto.precio }}</td>

        </tr>

    </tbody>

    </table>

    </div>

</template>

<script>

import axios from "axios";

export default {

data() {

return {

productos: []

}

},

mounted() {

this.listar();

},

methods: {

listar() {

axios.get("https://proyecto-production-b957.up.railway.app/api/inventario")

.then(response => {

this.productos = response.data;

})

.catch(error => {

console.log(error);

});

}

}

}

</script>