<template>

<div>

<h2>Formulario Inventario</h2>

<form @submit.prevent="guardar">

<label>Nombre Producto</label>

<input
type="text"
v-model="nombreProducto"
required>

<br><br>

<label>Cantidad</label>

<input
type="number"
v-model="cantidad"
required>

<br><br>

<label>Precio</label>

<input
type="number"
v-model="precio"
required>

<br><br>

<button type="submit">

Guardar

</button>

</form>

</div>

</template>

<script>

import axios from "axios";

export default{

data(){

return{

nombreProducto:"",
cantidad:"",
precio:""

}

},

methods:{

guardar(){

axios.post("https://proyecto-production-b957.up.railway.app/api/inventario",{

nombreProducto:this.nombreProducto,
cantidad:this.cantidad,
precio:this.precio

})

.then(()=>{

alert("Producto guardado");

this.nombreProducto="";
this.cantidad="";
this.precio="";

this.$emit("actualizar-tabla");

})

.catch((error)=>{

console.log(error);

});

}

}

}

</script>